const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function ask(message){const dialog=$('#service-confirm');if(dialog.open)return Promise.resolve(false);$('#confirm-message').textContent=message;const previous=document.activeElement;dialog.showModal();return new Promise(resolve=>{const finish=value=>{dialog.close();previous?.focus();resolve(value);};$('#confirm-no').onclick=()=>finish(false);$('#confirm-yes').onclick=()=>finish(true);dialog.oncancel=e=>{e.preventDefault();finish(false);};});}
let user=null,cap={},projects=[],files=[],jobs=[],results=[],view='home',timer,authMode='login';const statuses={queued:'排队中',running:'处理中',completed:'已完成',failed:'失败',cancelled:'已取消'};
const date=v=>new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
const notify=message=>{$('#notice').textContent=message;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').textContent='',5000);};
async function api(path,data){const response=await fetch('/api'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const value=await response.json();if(!response.ok){if(response.status===401&&user){user=null;clearInterval(timer);renderAuth();}throw new Error(value.error||'请求未完成');}return value;}
function optionProjects(){return '<option value="">独立任务 / 未归入项目</option>'+projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('');}
function renderAuth(){clearInterval(timer);$('#logout').hidden=true;$('#app').innerHTML=`<section class="card auth"><h1>${authMode==='register'?'创建服务账户':'登录服务账户'}</h1><p class="muted">账户与内容保存在这台本地服务的数据库中，与原来的浏览器体验数据独立。邮箱尚未验证，请勿用于正式对外服务。</p><form id="auth-form">${authMode==='register'?'<label for="name">昵称</label><input id="name" autocomplete="nickname" maxlength="30" required>':''}<label for="email">邮箱</label><input id="email" type="email" autocomplete="username" maxlength="254" required><label for="password">密码（至少 10 个字符）</label><input id="password" type="password" autocomplete="${authMode==='register'?'new-password':'current-password'}" minlength="10" maxlength="128" required><p id="auth-error" role="alert" class="error"></p><div class="actions"><button class="primary">${authMode==='register'?'注册并进入':'登录'}</button><button id="switch-auth" type="button">${authMode==='register'?'已有账户，登录':'注册新账户'}</button></div></form></section>`;$('#switch-auth').onclick=()=>{authMode=authMode==='login'?'register':'login';renderAuth();};$('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{user=(await api('/auth/'+authMode,{email:$('#email').value,password:$('#password').value,...(authMode==='register'?{name:$('#name').value}:{})})).user;await enter();}catch(err){$('#auth-error').textContent=err.message;}finally{button.disabled=false;}};}
async function refresh(){[projects,files,jobs,results]=await Promise.all(['/projects','/files','/jobs','/results'].map(p=>api(p).then(v=>v.items)));}
async function enter(){await refresh();$('#logout').hidden=false;render();clearInterval(timer);timer=setInterval(async()=>{if(!user)return;try{jobs=(await api('/jobs')).items;if($('#job-list'))renderJobs();}catch(err){notify(err.message);}},3000);}
const nav=[['home','服务概览'],['projects','项目与文件'],['tasks','任务中心'],['results','我的成果'],['usage','用量记录'],['membership','会员与订单'],['help','帮助与反馈']];
function render(){if(!user)return;$('#app').innerHTML=`<h1>你好，${esc(user.name)}</h1><p class="muted">真实账户 · 服务端保存 · ${esc(user.email)}</p><div class="banner">这是本地开发版本：项目、原件、任务和成果保存到本机服务。${cap.ai?`AI 已配置，提交润色会将正文发送至 ${esc(cap.aiProvider)}，请核对材料权限。`:'AI 未配置，不生成模拟内容。'} 支付与全网学术检索尚未开放。</div><nav class="tabs" aria-label="服务工作台">${[...nav,...(user.role==='admin'?[['admin','管理后台']]:[])].map(([id,name])=>`<button data-view="${id}" aria-pressed="${view===id}">${name}</button>`).join('')}</nav><div id="view"></div>`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=async()=>{if(dirty()&&!await ask('当前表单尚未提交，切换会丢弃输入。是否继续？'))return;view=b.dataset.view;await refresh();render();});renderView().catch(err=>notify(err.message));}
const formSnapshots=new WeakMap();
function formSnapshot(form){return JSON.stringify([...form.elements].filter(e=>['INPUT','SELECT','TEXTAREA'].includes(e.tagName)).map(e=>e.type==='file'?[...e.files].map(f=>[f.name,f.size,f.lastModified]):e.type==='checkbox'?e.checked:e.value));}
function rememberForms(){document.querySelectorAll('#view form').forEach(f=>{if(!formSnapshots.has(f))formSnapshots.set(f,formSnapshot(f));});}
new MutationObserver(rememberForms).observe($('#app'),{childList:true,subtree:true});
function dirty(){return [...document.querySelectorAll('#view form')].some(f=>formSnapshots.has(f)&&formSnapshot(f)!==formSnapshots.get(f));}
window.addEventListener('beforeunload',e=>{if(dirty())e.preventDefault();});
function resultRows(){return results.length?results.map(r=>`<div class="row"><span><b>${esc(r.title)}</b><br><small class="muted">${esc(r.type)} · ${date(r.created_at)}</small></span><button data-result="${r.id}">打开成果</button></div>`).join(''):'<p class="muted">还没有成果，先上传并解析文件或创建任务。</p>';}
async function renderView(){const target=$('#view');if(view==='home'){target.innerHTML=`<div class="grid"><section class="card"><h2>你的研究资料</h2><p>${projects.length} 个项目 · ${files.length} 份原件 · ${results.length} 份成果</p><p class="muted">保存到服务端后，同一服务地址下的另一浏览器登录可继续查看。当前仅绑定本机地址。</p><a href="/workspace.html#home">使用现有本地写作、PPT、排版和科研绘图工具 →</a></section><section class="card"><h2>真实任务状态</h2><div id="job-list"></div></section><section class="card full"><h2>最近成果</h2>${resultRows()}</section></div>`;renderJobs();wireResults();return;}
if(view==='projects'){target.innerHTML=`<div class="grid"><section class="card"><h2>新建项目</h2><form id="project-form"><label for="project-title">项目名称</label><input id="project-title" maxlength="200" required><label for="degree">学段</label><select id="degree"><option>专科</option><option selected>本科</option><option>硕士</option><option>博士</option><option>科研人员</option></select><label for="major">专业（可选）</label><input id="major" maxlength="100"><div class="actions"><button class="primary">保存到服务端</button></div></form></section><section class="card"><h2>上传论文原件</h2><form id="upload-form"><label for="upload-project">所属项目</label><select id="upload-project">${optionProjects()}</select><label for="upload-file">TXT / DOCX / 文本 PDF（最大 2MB）</label><input id="upload-file" type="file" accept=".txt,.docx,.pdf" required><p class="muted">上传会保存原件，正文解析作为独立后台任务执行。扫描 PDF 暂无 OCR。</p><div class="actions"><button class="primary">上传并解析</button></div></form></section><section class="card"><h2>我的项目</h2>${projects.map(p=>`<div class="row"><span><b>${esc(p.title)}</b><br><small>${esc(p.degree)} · ${esc(p.major)} · ${date(p.updated_at)}</small></span><span class="tag">${files.filter(f=>f.project_id===p.id).length} 份原件</span></div>`).join('')||'<p>尚无项目</p>'}</section><section class="card"><h2>原件列表</h2>${files.map(f=>`<div class="row"><span><b>${esc(f.name)}</b><br><small>${f.bytes} 字节</small></span><a href="/api/files/${f.id}/download">下载原件</a></div>`).join('')||'<p>尚无文件</p>'}</section></div>`;$('#project-form').onsubmit=e=>submit(e,async()=>{await api('/projects',{title:$('#project-title').value,degree:$('#degree').value,major:$('#major').value});await refresh();render();notify('项目已保存到服务端');});$('#upload-form').onsubmit=e=>submit(e,async()=>{const f=$('#upload-file').files[0];if(f.size>2*1024*1024)throw new Error('文件最大 2MB');const projectId=$('#upload-project').value;const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const file=await api('/files',{name:f.name,data:btoa(binary),projectId});await api('/jobs',{type:'parse',fileId:file.id,projectId,idempotencyKey:crypto.randomUUID()});view='tasks';await refresh();render();notify('原件已保存，正文解析已加入队列');});return;}
if(view==='tasks'){target.innerHTML=`<div class="grid"><section class="card"><h2>创建处理任务</h2><form id="task-form"><label for="task-type">任务类型</label><select id="task-type"><option value="polish">学术润色${cap.ai?'':'（AI 未配置）'}</option><option value="review">导师意见修改${cap.ai?'':'（AI 未配置）'}</option><option value="compare">用户材料查重（不检索全网）</option></select><label for="task-project">所属项目</label><select id="task-project">${optionProjects()}</select><label for="task-text">原文（AI 最多 6,000 字符，材料查重最多 8,000）</label><textarea id="task-text" required maxlength="8000"></textarea><label for="requirements">修改要求 / 导师意见（可选）</label><textarea id="requirements" maxlength="2000"></textarea><div id="sources-form" hidden><label for="source-title">实际来源标题</label><input id="source-title" maxlength="200"><label for="source-text">实际来源正文</label><textarea id="source-text" maxlength="8000"></textarea><label for="source-url">来源 URL（可选）</label><input id="source-url" type="url"><label for="source-doi">DOI（可选，未核验）</label><input id="source-doi" maxlength="200"><label for="source-authors">作者（可选）</label><input id="source-authors" maxlength="100"><label for="source-year">年份（可选）</label><input id="source-year" pattern="[0-9]{4}" maxlength="4"></div><p class="muted" id="task-note"></p><div class="actions"><button class="primary" id="task-submit">提交真实任务</button></div></form></section><section class="card"><h2>任务队列</h2><p class="muted">状态来自服务端，每 3 秒更新。关闭页面不会停止已提交任务。重试 AI 任务可能产生额外的模型服务费用。</p><div id="job-list"></div></section></div>`;const change=()=>{const compare=$('#task-type').value==='compare';$('#task-text').maxLength=compare?8000:6000;$('#sources-form').hidden=!compare;$('#source-title').required=compare;$('#source-text').required=compare;$('#task-submit').disabled=!compare&&!cap.ai;$('#task-note').textContent=compare?'仅比较实际输入材料；相似度由确定性文本算法计算，不提供语义分数或全网检测结论。':cap.ai?`正文和要求将发送至 ${cap.aiProvider}。修改结果需人工确认，不保证检测分数。`:'需要配置模型接口后才能提交，不会返回模拟改写。';};$('#task-type').onchange=change;change();renderJobs();$('#task-form').onsubmit=e=>submit(e,async()=>{const type=$('#task-type').value;await api('/jobs',{type,text:$('#task-text').value,requirements:$('#requirements').value,projectId:$('#task-project').value,title:'用户材料查重',sources:type==='compare'?[{title:$('#source-title').value,text:$('#source-text').value,url:$('#source-url').value,doi:$('#source-doi').value,authors:$('#source-authors').value?[$('#source-authors').value]:[],year:$('#source-year').value}]:undefined,idempotencyKey:crypto.randomUUID()});$('#task-form').reset();change();formSnapshots.set($('#task-form'),formSnapshot($('#task-form')));jobs=(await api('/jobs')).items;renderJobs();notify('任务已提交');});return;}
if(view==='results'){target.innerHTML=`<section class="card"><h2>服务端成果</h2>${resultRows()}</section><div id="result-detail"></div>`;wireResults();return;}
if(view==='usage'){const data=await api('/usage');target.innerHTML=`<section class="card"><h2>模型用量</h2><p class="muted">仅记录成功调用且服务实际返回的 Token 数，缺失字段显示未知。当前未启用扣费，不代表会员额度；第三方模型接口可能按自己的规则收费。</p>${data.items.map(v=>`<div class="row"><span>${esc(v.model)} · ${date(v.created_at)}</span><span>输入 ${v.input_tokens??'未知'} / 输出 ${v.output_tokens??'未知'}</span></div>`).join('')||'<p>还没有真实模型调用记录</p>'}</section>`;return;}
if(view==='membership'){const data=await api('/products');target.innerHTML=`<section class="card"><h2>会员与订单</h2><p class="muted">商品目录已保存到数据库。价格单位、额度、有效期与退款规则尚未确定，付款及订单创建关闭。</p>${data.items.map(p=>`<div class="row"><b>${esc(p.title)}</b><span class="tag">规则待确认 · 不可购买</span></div>`).join('')}<div class="actions"><a href="/workspace.html#membership/plans">查看参考方案</a></div></section>`;return;}
if(view==='help'){const data=await api('/feedback');target.innerHTML=`<div class="grid"><section class="card"><h2>反馈给本地服务</h2><form id="feedback-form"><label for="feedback">问题或建议</label><textarea id="feedback" required maxlength="3000"></textarea><p class="muted">只提交到当前本机服务，不自动发送给外部客服。</p><button class="primary">保存反馈</button></form></section><section class="card"><h2>我的反馈记录</h2>${data.items.map(v=>`<div class="row"><span>${esc(v.body)}<br><small>${date(v.created_at)}</small></span></div>`).join('')||'<p>暂无反馈</p>'}</section></div>`;$('#feedback-form').onsubmit=e=>submit(e,async()=>{await api('/feedback',{text:$('#feedback').value});render();notify('反馈已保存到本地服务');});return;}
if(view==='admin'){const data=await api('/admin');target.innerHTML=`<section class="card"><h2>本地管理后台</h2><p>${data.users.length} 个账户 · ${data.jobs.length} 条近期任务 · ${data.feedback.length} 条近期反馈</p><h2>任务追踪</h2>${data.jobs.map(j=>`<div class="row"><span>${esc(j.id)}<br><small>用户 ${esc(j.user_id)} · ${esc(j.type)}</small><p class="error">${esc(j.error||'')}</p></span><span class="tag">${statuses[j.status]}</span></div>`).join('')}<h2>反馈</h2>${data.feedback.map(f=>`<div class="row"><span>${esc(f.category)} · ${esc(f.body)}</span></div>`).join('')||'<p>暂无反馈</p>'}</section>`;}}
async function submit(e,fn){e.preventDefault();e.submitter.disabled=true;try{await fn();}catch(err){notify(err.message);}finally{e.submitter.disabled=e.submitter.id==='task-submit'&&$('#task-type')?.value!=='compare'&&!cap.ai;}}
function renderJobs(){const target=$('#job-list');if(!target)return;target.innerHTML=jobs.slice(0,20).map(j=>`<div class="row"><span><b>${esc({parse:'正文解析',polish:'学术润色',review:'导师意见修改',compare:'材料查重'}[j.type])}</b><br><small>${date(j.created_at)} · 第 ${j.attempt} 次执行</small>${j.error?`<p class="error">${esc(j.error)}</p>`:''}<div class="actions">${j.result_id?`<button data-result="${j.result_id}">查看成果</button>`:''}${['queued','running'].includes(j.status)?`<button data-job="${j.id}" data-action="cancel">取消任务</button>`:''}${j.status==='failed'?`<button data-job="${j.id}" data-action="retry">重试</button>`:''}</div></span><span class="tag ${j.status}">${statuses[j.status]}</span></div>`).join('')||'<p class="muted">暂无任务</p>';document.querySelectorAll('[data-job]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{if(b.dataset.action==='retry'&&!await ask('重新执行可能重复调用模型并产生第三方费用，是否继续？'))return;await api(`/jobs/${b.dataset.job}/${b.dataset.action}`,{});jobs=(await api('/jobs')).items;renderJobs();}catch(err){notify(err.message);}finally{b.disabled=false;}});wireResults();}
function wireResults(){document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>showResult(b.dataset.result).catch(err=>notify(err.message)));}
async function showResult(id){if(dirty()&&!await ask('当前输入未提交，打开成果会丢弃输入。是否继续？'))return;const item=(await api('/results/'+id)).item;view='results';results=(await api('/results')).items;render();await Promise.resolve();const b=item.body;const target=$('#result-detail');if(!target)return;let content='';let exportText='';if(item.type==='parse'){exportText=b.text;content=`<p class="muted">${esc(b.fileName)} · ${b.characters} 字符 · ${esc(b.scope)}</p><pre>${esc(b.text)}</pre>`;}else if(item.type==='compare'){exportText=JSON.stringify(b,null,2);content=`<div class="banner">${esc(b.scope)}。语义分析未接入。来源信息由用户提供，未核验。</div><h2>文本相似度 ${(b.ratio*100).toFixed(1)}% · 去除已识别引用 ${(b.uncitedRatio*100).toFixed(1)}%</h2><p>${b.totalChars} 字 · 相似 ${b.similarChars} 字 · 命中 ${b.sourceCount} 份材料</p><p class="muted">${esc(b.citationPolicy)}</p>${b.sections.map(s=>`<section class="source"><h2>${esc(s.title)} · ${(s.ratio*100).toFixed(1)}%</h2>${s.paragraphs.map(p=>`<details><summary>${p.similarChars?'发现相似片段':'未发现相似片段'} · ${p.totalChars} 字</summary><pre>${esc(p.text)}</pre>${p.matches.map(m=>{const source=b.sources.find(v=>v.id===m.sourceId);return `<div class="compare"><pre><b>原文片段</b>\n${esc(Array.from(p.text).slice(...m.range).join(''))}</pre><pre><b>${esc(source.title)}</b>\n${esc(Array.from(source.text).slice(...m.sourceRange).join(''))}\n文本相似度：${m.textScore*100}%\n语义相似度：未计算\n引用状态：${m.citationStatus==='verified_quotation'?'已识别引用':'需人工核对'}\n作者：${esc(source.authors.join('、')||'未填写')} · 年份：${esc(source.year||'未填写')}\nDOI：${esc(source.doi||'未填写')}\n来源：用户材料${source.url?`\n<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">查看来源网页</a>`:''}</pre></div>`;}).join('')}</details>`).join('')}</section>`).join('')}`;}else{const versions=(await api(`/results/${id}/revisions`)).items;exportText=versions[0]?.body||b.suggestion;content=`<p class="muted">模型 ${esc(b.model)} · 修改建议需人工核对 · 原件与模型建议保留不变</p><div class="compare"><section><h2>原文</h2><pre>${esc(b.original)}</pre></section><section><h2>修改建议 / 你的编辑稿</h2><form id="revision-form"><textarea id="revision-text" maxlength="100000" required>${esc(exportText)}</textarea><div class="actions"><button class="primary">保存新版本</button><button type="button" id="original-suggestion">恢复模型建议到编辑区</button></div></form></section></div><h2>已保存版本</h2>${versions.map(v=>`<details><summary>${date(v.created_at)}</summary><pre>${esc(v.body)}</pre></details>`).join('')||'<p>尚无人工编辑版本</p>'}`;}
target.innerHTML=`<section class="card detail"><h1>${esc(item.title)}</h1><div class="actions"><button id="export-result">导出成果</button></div>${content}</section>`;$('#export-result').onclick=()=>{const text=item.type==='compare'?exportText:item.type==='parse'?b.text:$('#revision-text').value;const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=item.type==='compare'?'材料查重报告.json':'PaperKnow成果.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};if($('#revision-form')){$('#original-suggestion').onclick=async()=>{if(await ask('替换当前编辑区为原始模型建议？已保存版本仍保留。'))$('#revision-text').value=b.suggestion;};$('#revision-form').onsubmit=e=>submit(e,async()=>{await api(`/results/${id}/revisions`,{text:$('#revision-text').value});formSnapshots.set($('#revision-form'),formSnapshot($('#revision-form')));await showResult(id);notify('新版本已保存');});}target.scrollIntoView({behavior:'smooth'});}
$('#logout').onclick=async()=>{if(dirty()&&!await ask('当前输入未提交，是否退出？'))return;try{await api('/auth/logout',{});user=null;renderAuth();}catch(err){notify(err.message);}};
try{cap=await api('/capabilities');try{user=(await api('/auth/me')).user;await enter();}catch{renderAuth();}}catch(err){$('#app').innerHTML='<section class="card"><h1>服务连接失败</h1><p>请启动新版 PaperKnow 本地服务后刷新。</p></section>';notify(err.message);}
